INSERT INTO public.quiz_questions (group_id, language, category, question, options, correct_index, explanation, source, is_active, sort_order)
VALUES
('9ad708c8-79ed-5314-bd86-bdda535a5ec0'::uuid, 'az', 'pregnancy', 'Hamiləlikdə gündəlik fol turşusu tövsiyəsi nə qədərdir?', '["4 qram", "40 mikroqram", "400 mikroqram", "Ehtiyac yoxdur"]'::jsonb, 2, 'Həkim başqa doza yazmayıbsa, gündə 400 mikroqram. Ən yaxşısı hamiləlikdən əvvəl başlamaqdır.', 'ÜST', true, 1),
('aba2abe2-e877-5c5c-9281-bea1e7330cb0'::uuid, 'az', 'pregnancy', 'Hamiləlikdə gündə nə qədər kofein təhlükəsiz sayılır?', '["1000 mq-a qədər", "200 mq-a qədər", "Məhdudiyyət yoxdur", "500 mq-a qədər"]'::jsonb, 1, '200 mq təxminən 1-2 fincan qəhvədir. Çay, kola və şokoladda da kofein var.', 'ACOG', true, 2),
('764c7db0-c181-5226-99d1-b24b6e83b65c'::uuid, 'az', 'pregnancy', 'Hamiləlikdə hansı qidadan çəkinmək lazımdır?', '["Yaxşı bişmiş yumurta", "Pasterizə olunmuş süd", "Pasterizə olunmamış süddən pendir", "Qatıq"]'::jsonb, 2, 'Pasterizə olunmamış məhsullarda listeriya ola bilər. Bu infeksiya hamiləlikdə təhlükəlidir.', 'CDC', true, 3),
('649ece27-7b35-584a-a619-e0b4672669c0'::uuid, 'az', 'pregnancy', 'Hamiləlik müddəti adətən neçə həftə hesablanır?', '["Təxminən 40 həftə", "36 həftə", "32 həftə", "44 həftə"]'::jsonb, 0, 'Müddət son aybaşının ilk günündən hesablanır. 37-42-ci həftələr arası doğuş vaxtında sayılır.', 'ÜST', true, 4),
('3f3efc54-7396-53bb-a919-279347d10208'::uuid, 'az', 'pregnancy', 'Hamiləlikdə spirtli içkinin təhlükəsiz miqdarı nə qədərdir?', '["Yalnız şərab olar", "Gündə bir qədəh", "Təhlükəsiz miqdar yoxdur", "Yalnız son trimestrdə olar"]'::jsonb, 2, 'Spirt körpəyə plasenta ilə keçir və hamiləliyin istənilən dövründə zərər verə bilər.', 'CDC', true, 5),
('56a9dda0-a46a-5fc9-b8c4-051748788603'::uuid, 'az', 'pregnancy', 'Hamiləlik diabeti testi adətən hansı həftələrdə edilir?', '["1-4-cü həftələrdə", "36-40-cı həftələrdə", "24-28-ci həftələrdə", "8-10-cu həftələrdə"]'::jsonb, 2, 'Risk yüksəkdirsə, həkim testi daha tez də edə bilər.', 'ACOG', true, 6),
('adc3c12f-d134-5fbf-8f2a-a27228e7e8de'::uuid, 'az', 'pregnancy', 'İlk hamiləlikdə körpənin hərəkətləri adətən nə vaxt hiss olunur?', '["36-cı həftədə", "8-ci həftədə", "30-cu həftədə", "18-20-ci həftələrdə"]'::jsonb, 3, 'İlk hamiləlikdə çox vaxt 18-20-ci həftələrdə, sonrakılarda bir az tez hiss olunur.', 'NHS', true, 7),
('07316547-7e23-55fa-8b21-ac66b61b8e9f'::uuid, 'az', 'pregnancy', 'Hamiləlikdə hansı balığı yeməmək lazımdır?', '["Qılınc balığı", "Qızılbalıq", "Sardina", "Ağ balıq (treska)"]'::jsonb, 0, 'Qılınc balığında civə çoxdur. Qızılbalıq və sardina kimi az civəli balıqlar faydalıdır.', 'FDA', true, 8),
('059c86e7-75c8-5782-a322-66d8a2391d82'::uuid, 'az', 'pregnancy', 'Hamiləliyin 20-ci həftəsindən sonra hansı ağrıkəsicidən həkimsiz çəkinmək lazımdır?', '["Bitki çayı", "İbuprofen", "Heç biri riskli deyil", "Vitamin C"]'::jsonb, 1, 'İbuprofen kimi dərmanlar 20-ci həftədən sonra körpənin böyrəklərinə təsir edə bilər. Hər dərmanı həkimlə razılaşdır.', 'FDA', true, 9),
('9388545a-ce4c-5f6d-b2f2-13dc59891852'::uuid, 'az', 'pregnancy', 'Hansı əlamət preeklampsiyanı göstərə bilər?', '["Axşam ayaqlarda yorğunluq", "Səhərlər yüngül ürəkbulanma", "Güclü baş ağrısı, görmə pozğunluğu, qəfil ödem", "İştahanın artması"]'::jsonb, 2, 'Bu əlamətlər olarsa, dərhal həkimə müraciət et.', 'ACOG', true, 10),
('d25d8bb1-293c-5d34-8712-8dd34820abed'::uuid, 'az', 'pregnancy', 'İkinci trimestrdə gündə təxminən nə qədər əlavə kalori lazımdır?', '["1000 kkal", "Heç əlavə lazım deyil", "Təxminən 340 kkal", "2000 kkal"]'::jsonb, 2, '"İki nəfərlik yemək" lazım deyil. Üçüncü trimestrdə bu, təxminən 450 kkal olur.', 'ACOG', true, 11),
('852144db-0b3e-5bc6-8618-c1f85e28d19e'::uuid, 'az', 'pregnancy', '28-ci həftədən sonra necə yatmaq tövsiyə olunur?', '["Fərqi yoxdur", "Arxası üstə", "Qarnı üstə", "Yan üstə"]'::jsonb, 3, 'Yan üstə yatmaq körpəyə qan axınını yaxşılaşdırır. Gecə arxa üstə oyansan, narahat olma, sadəcə yanına çevril.', 'NHS', true, 12),
('8d8ef69c-27d6-56e0-9f5d-802abcac8c26'::uuid, 'az', 'pregnancy', 'Hamiləlikdə pişik tualetini təmizləmək hansı infeksiya riskini artırır?', '["Angina", "Toksoplazmoz", "Qrip", "Suçiçəyi"]'::jsonb, 1, 'Mümkünsə bu işi başqası etsin, yoxsa əlcəkdən istifadə et və əllərini yaxşıca yu.', 'CDC', true, 13),
('c211d094-55e3-5c80-9f06-27cc27e06240'::uuid, 'az', 'pregnancy', 'Hamiləlikdə fiziki aktivlik üçün ümumi tövsiyə hansıdır?', '["Yalnız ağır çəki qaldırmaq", "Tamamilə qadağandır", "Həkim icazəsi ilə həftədə 150 dəqiqə orta aktivlik", "Gündə 5 dəqiqədən çox olmaz"]'::jsonb, 2, 'Gəzinti, üzgüçülük və yoqa kimi aktivliklər çox vaxt təhlükəsizdir.', 'ACOG', true, 14),
('94a1262b-4ad0-58ce-83bf-c79805a80d35'::uuid, 'az', 'pregnancy', 'Hamiləlikdə qrip peyvəndi haqqında hansı fikir doğrudur?', '["Faydası yoxdur", "İstənilən trimestrdə tövsiyə olunur", "Yalnız doğuşdan sonra vurulur", "Hamiləlikdə qadağandır"]'::jsonb, 1, 'Peyvənd ananı qoruyur, anticisimlər isə ilk aylarda körpəyə də keçir.', 'CDC', true, 15),
('d033842e-25b6-5645-8377-414a1de27db4'::uuid, 'az', 'pregnancy', 'Suyun gəlməsi ilə nə etmək lazımdır?', '["İsti vannaya girmək", "Həkimə və ya doğum evinə müraciət etmək", "İki gün gözləmək", "Heç nə etməmək"]'::jsonb, 1, 'Suyun rəngini və vaxtını qeyd et. Yaşıl və ya qəhvəyi rəng varsa, dərhal xəbər ver.', 'NHS', true, 16),
('afb425d8-43fe-521d-afc9-15b17773385a'::uuid, 'az', 'pregnancy', 'Hamiləlikdə səhər ürəkbulanması çox vaxt nə vaxt azalır?', '["30-cu həftədə", "Yalnız doğuşdan sonra", "4-cü həftədə", "12-16-cı həftələrdə"]'::jsonb, 3, 'Çox güclü qusma və su içə bilməmək olarsa, həkimə müraciət et.', 'NHS', true, 17),
('f06b116e-fed5-5cbe-b016-9e5f997c9dee'::uuid, 'az', 'pregnancy', 'Hamiləlikdə dəmir çatışmazlığının tez-tez görülən əlaməti hansıdır?', '["Saçın sürətli uzanması", "Güclü iştah", "Halsızlıq və solğunluq", "Görmənin yaxşılaşması"]'::jsonb, 2, 'Qan analizi ilə yoxlanılır. Dəmir əlavəsini həkim təyin edir.', 'ÜST', true, 18),
('4469cf3d-16c2-598b-951f-73ef448aa242'::uuid, 'az', 'baby_food', 'Körpəyə ilk 6 ayda nə vermək tövsiyə olunur?', '["Ana südü və bir az su", "Ana südü və meyvə şirəsi", "Yalnız ana südü və ya süd qarışığı", "Ana südü və bitki çayı"]'::jsonb, 2, 'Bu yaşda ana südü suyu da əvəz edir. Əlavə su, çay və şirə lazım deyil.', 'ÜST', true, 19),
('8d5e625e-89ba-5ee8-a3f8-396c8c17127c'::uuid, 'az', 'baby_food', 'Bal neçə yaşdan verilə bilər?', '["1 yaşdan", "3 yaşdan", "9 aydan", "6 aydan"]'::jsonb, 0, 'Bir yaşa qədər bal vermək olmaz: körpə botulizmi riski var.', 'AAP', true, 20),
('1803bacd-a662-5fa4-b080-87eed808e1a4'::uuid, 'az', 'baby_food', 'Əlavə qidaya təxminən neçə aylıqda başlanılır?', '["2 aylıqda", "Təxminən 6 aylıqda", "3 aylıqda", "1 yaşda"]'::jsonb, 1, 'Körpə dik oturursa və qidaya maraq göstərirsə, hazırdır.', 'ÜST', true, 21),
('b5133366-1b95-50e4-a83c-94f8ca40fdfa'::uuid, 'az', 'baby_food', 'İnək südü əsas içki kimi neçə yaşdan verilə bilər?', '["6 aydan", "9 aydan", "3 aydan", "1 yaşdan"]'::jsonb, 3, 'Bir yaşa qədər əsas süd ana südü və ya süd qarışığıdır. Qatıq və pendir isə daha tez verilə bilər.', 'AAP', true, 22),
('5f544bd9-b905-5111-848d-ed282e070db4'::uuid, 'az', 'baby_food', 'Körpənin yeməyinə duz neçə yaşa qədər əlavə edilmir?', '["1 yaşa qədər", "Duz həmişə olar", "3 aylığa qədər", "6 aylığa qədər"]'::jsonb, 0, 'Körpənin böyrəkləri əlavə duzu hələ çəkə bilmir.', 'NHS', true, 23),
('269f421a-c20f-566a-be0b-18debb93e0bc'::uuid, 'az', 'baby_food', 'Bütöv qoz-fındıq neçə yaşa qədər verilmir?', '["2 yaşa qədər", "1 yaşa qədər", "5 yaşa qədər", "6 aylığa qədər"]'::jsonb, 2, 'Bütöv qoz-fındıq boğulma riski yaradır. Döyülmüş və ya pasta halında daha tez vermək olar.', 'NHS', true, 24),
('c4a668c6-f6b5-546e-89fe-d9a639ffef2e'::uuid, 'az', 'baby_food', 'Üzümü kiçik uşağa necə vermək lazımdır?', '["Uzununa dörd hissəyə bölərək", "Qabığı ilə bütöv", "Yalnız yarıya bölərək", "Bütöv"]'::jsonb, 0, 'Bütöv üzüm nəfəs yolunu tam tıxaya bilər.', 'NHS', true, 25),
('a8af98b6-8c26-5c0f-9bb9-97fbf1536013'::uuid, 'az', 'baby_food', 'Ana südü ilə qidalanan körpəyə hansı vitamin əlavə tövsiyə olunur?', '["C vitamini", "D vitamini", "A vitamini", "B12 vitamini"]'::jsonb, 1, 'Adətən gündə 400 BV, ilk günlərdən. Dozanı həkimlə razılaşdır.', 'AAP', true, 26),
('5725d2ad-8a07-56b5-8d3f-edaa0e167aad'::uuid, 'az', 'baby_food', 'Sağılmış ana südü otaq temperaturunda nə qədər saxlanıla bilər?', '["2 gün", "15 dəqiqə", "24 saat", "4 saata qədər"]'::jsonb, 3, 'Soyuducuda 4 günə, dondurucuda isə 6 aya qədər saxlamaq yaxşıdır.', 'CDC', true, 27),
('c993d375-f4f9-54b2-b389-563e23675b25'::uuid, 'az', 'baby_food', 'Sağılmış ana südü soyuducuda nə qədər saxlanıla bilər?', '["1 gün", "1 ay", "2 həftə", "4 günə qədər"]'::jsonb, 3, 'Südü qapının rəfində yox, soyuducunun arxa hissəsində saxla.', 'CDC', true, 28),
('b19b377d-ac70-5cb6-a914-df6638e2859d'::uuid, 'az', 'baby_food', 'Dondurulmuş ana südünü necə əritmək lazımdır?', '["Otaqda iki gün saxlayaraq", "Soyuducuda və ya ilıq suda", "Mikrodalğalı sobada", "Qaynadaraq"]'::jsonb, 1, 'Mikrodalğalı soba südü qeyri-bərabər qızdırır və ağızda yanıq yarada bilər.', 'CDC', true, 29),
('51fe3491-c3ef-5f88-b6c8-dc5bf6bf55bd'::uuid, 'az', 'baby_food', 'Süd qarışığını hazırlayarkən nəyə əməl etmək lazımdır?', '["Qutudakı ölçüyə dəqiq əməl etmək", "Toz çox olsun ki, toxluq versin", "Toz az olsun ki, yüngül olsun", "Şəkər əlavə etmək"]'::jsonb, 0, 'Yanlış nisbət körpənin böyrəklərinə və böyüməsinə zərər verə bilər.', 'ÜST', true, 30),
('ce3ef063-ede2-5bd6-953c-2c344c6007fd'::uuid, 'az', 'baby_food', 'Meyvə şirəsi neçə yaşa qədər tövsiyə olunmur?', '["6 aylığa qədər", "3 aylığa qədər", "1 yaşa qədər", "Hər yaşda olar"]'::jsonb, 2, 'Bütöv meyvə şirədən daha faydalıdır: lifi var, şəkəri azdır.', 'AAP', true, 31),
('6133c8a6-59de-5c9b-8721-2022bbdc9b6c'::uuid, 'az', 'baby_food', 'Yer fıstığı və yumurta kimi allergen qidaları nə vaxt təqdim etmək olar?', '["3 yaşdan sonra", "Yalnız 1 yaşdan sonra", "Heç vaxt", "Təxminən 6 aylıqda, kiçik miqdarda"]'::jsonb, 3, 'Erkən təqdim etmək allergiya riskini azalda bilər. Ağır ekzema varsa, əvvəl həkimlə danış.', 'AAP', true, 32),
('cb4bef2a-dbb8-5dc5-a026-ccf21d14a4e0'::uuid, 'az', 'baby_food', '6 aydan sonra hansı qida maddəsini əlavə qida ilə almaq xüsusilə vacibdir?', '["Dəmir", "Su", "Laktoza", "Duz"]'::jsonb, 0, 'Ət, yumurta, paxlalılar və dəmirlə zənginləşdirilmiş sıyıqlar yaxşı mənbədir.', 'ÜST', true, 33),
('ac0ad049-dd6f-519a-a3c3-c9388cbd828e'::uuid, 'az', 'baby_food', 'BLW (körpənin özünün yeməsi) üsulu nədir?', '["Körpə barmaq boyda qidaları özü tutub yeyir", "Yalnız qaşıqla püre verilir", "Gecə qidalanmasıdır", "Yalnız süd verilir"]'::jsonb, 0, 'Yemək yumşaq olmalı, körpə dik oturmalı və tək qalmamalıdır.', 'NHS', true, 34),
('5d1978ea-1681-5636-81d6-6d48f88ad675'::uuid, 'az', 'sleep', 'Körpəni yatırarkən ən təhlükəsiz vəziyyət hansıdır?', '["Yan üstə", "Arxası üstə", "Qarnı üstə", "Başının altında yastıqla"]'::jsonb, 1, 'Arxası üstə, bərk döşəkdə yatmaq ani körpə ölümü riskini azaldır.', 'AAP', true, 35),
('a0d5fd23-b4e1-5316-944e-446da59a4532'::uuid, 'az', 'sleep', 'Yeni doğulmuş körpə gündə təxminən neçə saat yatır?', '["20-22 saat", "10 saat", "6-8 saat", "14-17 saat"]'::jsonb, 3, 'Yuxu qısa hissələrə bölünür, çünki körpə tez-tez qidalanır.', 'NSF', true, 36),
('887808c0-991d-54a8-882b-e5e7640c0041'::uuid, 'az', 'sleep', 'Körpə beşiyində nə olmamalıdır?', '["Heç biri", "Yastıq, yorğan və yumşaq oyuncaqlar", "Döşəyə uyğun təbəqə", "Bərk döşək"]'::jsonb, 1, 'Boş beşik ən təhlükəsiz beşikdir. Yorğan yerinə yuxu kisəsi işlət.', 'AAP', true, 37),
('0e76b0ec-d620-5da3-9f5b-b25d29cb6501'::uuid, 'az', 'sleep', 'Körpə otağı üçün uyğun temperatur nə qədərdir?', '["16-20°C", "10-12°C", "26-28°C", "30°C"]'::jsonb, 0, 'Körpəni həddən artıq isti geyindirmə: qızma ani ölüm riskini artırır.', 'NHS', true, 38),
('85bd86e1-683e-52ab-ac57-ca48318bb753'::uuid, 'az', 'sleep', 'Körpə ilk aylarda harada yatmalıdır?', '["Valideynlərin otağında, öz beşiyində", "Valideynlərlə eyni yataqda", "Doğuşdan ayrı otaqda", "Divanda"]'::jsonb, 0, 'Ən azı ilk 6 ay eyni otaqda, amma ayrı yataqda yatmaq tövsiyə olunur.', 'AAP', true, 39),
('65ce0259-f0d7-51ee-8f54-b7920c106dbf'::uuid, 'az', 'sleep', 'Yuxuya gedərkən əmzik haqqında hansı fikir doğrudur?', '["Mütləq qadağandır", "Riski artırır", "Heç bir təsiri yoxdur", "Ani ölüm riskini azalda bilər"]'::jsonb, 3, 'Ana südü ilə qidalanmada əmziyi əmizdirmə yaxşı yerləşəndən sonra (adətən 3-4 həftə) ver.', 'AAP', true, 40),
('e2d47f50-6cb8-5442-8424-82aa14ea9622'::uuid, 'az', 'sleep', '3 aylıq körpə yuxular arasında təxminən nə qədər oyaq qala bilir?', '["60-90 dəqiqə", "4 saat", "6 saat", "15 dəqiqə"]'::jsonb, 0, 'Bu, "oyaqlıq pəncərəsi"dir. Yorğunluq əlamətlərini izləmək daha vacibdir.', 'Anacan', true, 41),
('6d19ae94-370c-5617-aca4-8e9831130700'::uuid, 'az', 'sleep', 'Qundaqlamağı nə vaxt dayandırmaq lazımdır?', '["Körpə çevrilməyə cəhd edəndə", "Heç vaxt", "1 yaşda", "6 aylıqda"]'::jsonb, 0, 'Bu, adətən 2 aylıq ətrafında olur. Qundaqlı körpə qarnı üstə çevrilsə, təhlükəlidir.', 'AAP', true, 42),
('ebc3179f-5cb7-5f4f-b814-cacdb651e374'::uuid, 'az', 'sleep', '1-2 yaşlı uşaq gündə təxminən neçə saat yatmalıdır?', '["6 saat", "18 saat", "8 saat", "11-14 saat"]'::jsonb, 3, 'Bu saata gündüz yuxusu da daxildir.', 'AASM', true, 43),
('9630c0fd-99d3-5bb0-b633-afc08c827daa'::uuid, 'az', 'sleep', 'Avtomobil oturacağında yuxuya getmiş körpəni evdə nə etmək lazımdır?', '["Beşiyə, düz səthə köçürmək", "Oturacaqda yatmağa qoymaq", "Divana qoymaq", "Yastığın üstünə qoymaq"]'::jsonb, 0, 'Oturmuş vəziyyətdə uzun yatmaq körpənin nəfəsini çətinləşdirə bilər.', 'AAP', true, 44),
('a541e25f-66a6-556c-9bc5-b7dee778c0c6'::uuid, 'az', 'sleep', 'Körpə ilə divanda yatmaq haqqında hansı fikir doğrudur?', '["Təhlükəsizdir", "Yastıqla olar", "Çox təhlükəlidir", "Gündüz olar"]'::jsonb, 2, 'Yorğunsansa və körpəni qucağında saxlayırsansa, onu beşiyə qoy.', 'AAP', true, 45),
('dbd649d6-d3af-5027-9fe3-404384423809'::uuid, 'az', 'sleep', 'Ən çox danışılan yuxu reqressiyası hansı yaşda olur?', '["1 həftəlikdə", "10 yaşda", "Təxminən 4 aylıqda", "3 yaşda"]'::jsonb, 2, 'Bu, yuxunun yetkinləşməsi ilə bağlıdır və adətən bir neçə həftəyə keçir.', 'Anacan', true, 46),
('400df24a-a930-5b20-a715-a38d8b630017'::uuid, 'az', 'development', 'Körpə sənə baxıb ilk dəfə adətən nə vaxt gülümsəyir?', '["6-8 həftəlikdə", "6 aylıqda", "İlk həftədə", "1 yaşda"]'::jsonb, 0, 'Bu, "sosial təbəssüm"dür və inkişafın ilk vacib addımlarından biridir.', 'CDC', true, 47),
('2aa51e6b-b779-5fc4-aa39-54d9d63c77f8'::uuid, 'az', 'development', 'Körpə başını adətən nə vaxt dik saxlamağa başlayır?', '["Təxminən 4 aylıqda", "1 yaşda", "9 aylıqda", "1 həftəlikdə"]'::jsonb, 0, 'Qarnı üstə oyun boyun əzələlərini gücləndirir.', 'CDC', true, 48),
('4099ed6d-4a98-5478-b506-df55d2d9d612'::uuid, 'az', 'development', 'Körpə adətən nə vaxt dəstəksiz oturur?', '["15 aylıqda", "2 aylıqda", "3 aylıqda", "6-9 aylıqda"]'::jsonb, 3, 'Hər körpənin öz tempi var. 9 aylıqda heç oturmursa, həkimlə danış.', 'CDC', true, 49),
('a91c7c85-ca1a-567c-a205-b2f0ae9365da'::uuid, 'az', 'development', 'Uşaqlar ilk addımlarını adətən hansı aralıqda atır?', '["6 aylıqda", "4 aylıqda", "3 yaşda", "9-18 aylıqda"]'::jsonb, 3, '18 aylıqda hələ yerimirsə, həkimə müraciət et.', 'CDC', true, 50),
('306012c2-58a9-5bb9-8627-5a424fd97dca'::uuid, 'az', 'development', 'İlk mənalı sözlər adətən nə vaxt deyilir?', '["6 həftəlikdə", "3 aylıqda", "2,5 yaşda", "Təxminən 12 aylıqda"]'::jsonb, 3, 'Körpəylə çox danışmaq, oxumaq və mahnı oxumaq nitqi inkişaf etdirir.', 'CDC', true, 51),
('968bfee4-17b3-5e83-97a4-e7464456e52c'::uuid, 'az', 'development', 'Qarnı üstə oyun (tummy time) nə üçün vacibdir?', '["Yuxunu uzadır", "Qidalanmanı əvəz edir", "Boyun və çiyin əzələlərini gücləndirir", "Heç bir faydası yoxdur"]'::jsonb, 2, 'Yalnız körpə oyaq olanda və sən yanında olanda et.', 'AAP', true, 52),
('b1d89c2e-202e-50b7-bc7f-55a8f5ed99f8'::uuid, 'az', 'development', '18 aydan kiçik uşaq üçün ekran vaxtı tövsiyəsi nədir?', '["Gündə 1 saat", "Video zəng istisna, tövsiyə olunmur", "Gündə 2 saat", "Məhdudiyyət yoxdur"]'::jsonb, 1, 'Bu yaşda canlı ünsiyyət və oyun beyin inkişafı üçün daha faydalıdır.', 'AAP', true, 53),
('33f74000-eb46-5e67-934e-d1ec2e528f69'::uuid, 'az', 'development', '2-5 yaşlı uşaq üçün gündəlik ekran vaxtı nə qədər olmalıdır?', '["4 saat", "Limitsiz", "Heç vaxt olmaz", "1 saata qədər"]'::jsonb, 3, 'Keyfiyyətli məzmunu uşaqla birlikdə izləmək daha faydalıdır.', 'ÜST', true, 54),
('4bb72a22-cd9d-5610-96e7-e9a81d04740d'::uuid, 'az', 'development', 'Baş və şəhadət barmağı ilə kiçik əşyanı tutmaq adətən nə vaxt başlayır?', '["4 aylıqda", "3 yaşda", "9-12 aylıqda", "2 aylıqda"]'::jsonb, 2, 'Bu tutuşla balaca əşyalar ağıza da gedir. Boğulma riskinə diqqət et.', 'CDC', true, 55),
('daf74725-4af9-5506-9b40-f348983a10ea'::uuid, 'az', 'development', 'Körpə adına adətən nə vaxt reaksiya verir?', '["İlk həftədə", "3 yaşda", "2 yaşda", "6-9 aylıqda"]'::jsonb, 3, '9 aylıqda adına heç reaksiya vermirsə, həkimlə danış.', 'CDC', true, 56),
('30b189eb-5dd6-5844-b72c-60ee666a6b2a'::uuid, 'az', 'development', 'İlk diş adətən nə vaxt çıxır?', '["Təxminən 6 aylıqda", "1 aylıqda", "Doğuşda", "2 yaşda"]'::jsonb, 0, 'Bəzi körpələrdə daha tez və ya gec çıxır, 1 yaşa qədər bu normaldır.', 'AAPD', true, 57),
('44abdbfa-2655-5ca3-a59b-16d413200669'::uuid, 'az', 'development', 'Körpəyə kitab oxumağa nə vaxt başlamaq olar?', '["Məktəbdən", "Doğuşdan", "2 yaşdan", "3 yaşdan"]'::jsonb, 1, 'Sənin səsin, ritm və şəkillər körpə sözləri anlamadan da nitqini inkişaf etdirir.', 'AAP', true, 58),
('186486bd-0b4b-5560-87de-8b1d5e27cefc'::uuid, 'az', 'development', 'Körpə heç emekləməyib birbaşa yeriyirsə, bu nə deməkdir?', '["Yerimək gecikəcək", "Bu, normal ola bilər", "Mütləq problemdir", "Hamısı 4 aylıqda emekləyir"]'::jsonb, 1, 'Bəzi uşaqlar sürünür, oturaraq hərəkət edir və ya birbaşa yeriyir.', 'NHS', true, 59),
('dfd8f3a0-6a25-5797-8723-c222d3ca4bd7'::uuid, 'az', 'development', 'İnkişafda hansı hal həkimlə danışmaq üçün ciddi səbəbdir?', '["Əvvəl bacardığı bacarıqları itirməsi", "1 yaşda oxumaması", "10 aylıqda yeriməməsi", "6 aylıqda danışmaması"]'::jsonb, 0, 'Bacarıq itirmək istənilən yaşda dərhal yoxlanmalıdır.', 'CDC', true, 60),
('ec02776e-ae77-5516-bdfa-eaf6a2bba9c2'::uuid, 'az', 'health', '3 aylıqdan kiçik körpədə hansı hərarətdə dərhal həkimə müraciət etmək lazımdır?', '["Yalnız 39,5°C-dən yuxarı", "37,2°C-dən yuxarı", "38,0°C və yuxarı", "Yalnız 40°C-dən yuxarı"]'::jsonb, 2, 'Bu yaşda 38°C hərarət belə ciddi xəstəliyin əlaməti ola bilər.', 'AAP', true, 61),
('1bd1b91b-0718-5d6f-81db-539678d19667'::uuid, 'az', 'health', 'Kiçik körpədə hərarəti ən dəqiq hansı üsulla ölçmək olar?', '["Rektal (düz bağırsaqdan)", "Alın zolağı ilə", "Dodaqla toxunaraq", "Əllə toxunaraq"]'::jsonb, 0, 'Qoltuqaltı ölçmək də olar, amma daha az dəqiqdir.', 'AAP', true, 62),
('d9ad7367-23d1-560d-b332-c9518d45b574'::uuid, 'az', 'health', 'Uşaqlara aspirin vermək olarmı?', '["Bəli, həmişə", "Yarım dozada olar", "Xeyr, Reye sindromu riski var", "Yalnız qızdırmada"]'::jsonb, 2, 'Uşaqlarda hərarəti salmaq üçün həkimin dediyi dərmanı işlət.', 'NHS', true, 63),
('0f75a6c5-c503-5a15-ab5a-7dd25b406132'::uuid, 'az', 'health', 'Hansı əlamət körpədə susuzlaşmanı göstərə bilər?', '["Tez-tez sidik", "Çox ağlayıb göz yaşı tökməsi", "Yaxşı iştah", "6-8 saat ərzində bezin quru qalması"]'::jsonb, 3, 'Quru ağız, göz yaşının olmaması və halsızlıq da əlamətdir. Həkimə müraciət et.', 'AAP', true, 64),
('302f86da-ee50-5dfa-95c8-ed12620a8cef'::uuid, 'az', 'health', 'Uşaq dərmanının dozası əsasən nəyə görə hesablanır?', '["Mövsümə görə", "Çəkisinə görə", "Boyuna görə", "Göz rənginə görə"]'::jsonb, 1, 'Qutudakı ölçü qabından istifadə et, mətbəx qaşığı ilə ölçmə.', 'AAP', true, 65),
('a803c6f0-1428-5f86-9be3-0d80a485404f'::uuid, 'az', 'health', 'Əlləri sabunla ən azı neçə saniyə yumaq lazımdır?', '["20 saniyə", "Lazım deyil", "5 dəqiqə", "2 saniyə"]'::jsonb, 0, 'Bu, təxminən "Ad günün mübarək" mahnısını iki dəfə oxumaq qədərdir.', 'CDC', true, 66),
('dc3a872c-837e-5742-9890-1d293bfd66ad'::uuid, 'az', 'health', 'Peyvəndlər haqqında hansı fikir doğrudur?', '["Bir yaşa qədər gözləmək lazımdır", "Milli təqvimə uyğun, gecikdirmədən vurulmalıdır", "Lazım deyil", "Yalnız xəstələnəndə vurulur"]'::jsonb, 1, 'Vaxtında vurulan peyvənd körpəni ən həssas dövrdə qoruyur.', 'ÜST', true, 67),
('69b83034-bf59-5d15-99ad-701fe422d46e'::uuid, 'az', 'health', 'Körpənin burnu tutulanda nə kömək edir?', '["Qaynar buxar", "Burna yağ damcısı", "Fizioloji duzlu su və burun aspiratoru", "Antibiotik"]'::jsonb, 2, 'Burnun açılması xüsusilə qidalanmadan və yuxudan əvvəl faydalıdır.', 'AAP', true, 68),
('ca194ce3-d560-5232-854b-e041eb4be374'::uuid, 'az', 'health', 'Antibiotiklər virus infeksiyasına təsir edirmi?', '["Hər soyuqdəymədə lazımdır", "Profilaktika üçün içilir", "Bəli, sağaldır", "Xeyr, təsir etmir"]'::jsonb, 3, 'Antibiotikləri yalnız həkim yazanda, deyilən müddət boyunca içmək lazımdır.', 'ÜST', true, 69),
('40e7308f-362a-5ee7-91fc-a776879c52dd'::uuid, 'az', 'health', 'Yeni doğulmuşda sarılıq nə vaxt həkimə müraciət tələb edir?', '["Qarına və ayaqlara yayılanda və ya körpə zəif əmdikdə", "Heç vaxt, həmişə normaldır", "Yalnız 1 aydan sonra", "Günəşdə saxlamaq kifayətdir"]'::jsonb, 0, 'Günəş işığı sarılığın müalicəsi deyil. Lazım olsa, həkim analiz və işıq terapiyası təyin edir.', 'AAP', true, 70),
('d24bebf7-ea7c-5026-8199-3d9119c8c7b6'::uuid, 'az', 'health', 'Körpədə ishal və qusma olanda nə etmək lazımdır?', '["Güclü çay vermək", "Qidalanmanı davam etdirmək, maye itkisini əvəz etmək", "Meyvə şirəsi vermək", "İki gün heç nə verməmək"]'::jsonb, 1, 'Susuzlaşma əlamətləri olarsa və ya körpə 6 aydan kiçikdirsə, həkimə müraciət et.', 'ÜST', true, 71),
('9d9bbd55-94c5-5819-80d3-a4981416386c'::uuid, 'az', 'health', 'Uşağın dişlərini nə vaxt fırçalamağa başlamaq lazımdır?', '["3 yaşdan", "Məktəbə gedəndə", "Bütün dişlər çıxandan sonra", "İlk diş çıxandan"]'::jsonb, 3, '3 yaşa qədər düyü dənəsi boyda flüorlu pasta kifayətdir.', 'AAP', true, 72),
('86e81ffa-dd0e-5b9a-a530-ed24b2e5efb5'::uuid, 'az', 'health', '6 aydan kiçik körpəni günəşdən necə qorumaq lazımdır?', '["Günəşləndirmək", "Kölgədə saxlamaq, nazik geyim və papaqla", "Yağ sürtmək", "Bütün bədənə güclü krem sürtmək"]'::jsonb, 1, 'Bu yaşda kremi yalnız kiçik açıq yerlərə, ehtiyac olanda çəkmək olar.', 'AAP', true, 73),
('0907e54e-9c01-5728-92d3-d8ad81305bb3'::uuid, 'az', 'health', 'Qızdırma qıcolması zamanı nə etmək lazımdır?', '["Yan üstə qoymaq, ağzına heç nə qoymamaq, vaxtı qeyd etmək", "Silkələmək", "Ağzına qaşıq qoymaq", "Su içirtmək"]'::jsonb, 0, '5 dəqiqədən uzun çəkərsə, təcili yardım çağır.', 'AAP', true, 74),
('7445f466-5111-510f-86ca-66166c820fa5'::uuid, 'az', 'health', 'Körpə sancısının "3-lər qaydası" nədir?', '["Gündə 3 saatdan çox, həftədə 3 gün, 3 həftə ağlamaq", "3 dəfə öskürmək", "3 gün qəbizlik", "Gündə 3 dəfə qusmaq"]'::jsonb, 0, 'Sancı çox vaxt 3-4 aylıqda keçir. Hərarət və ya qusma varsa, həkimə müraciət et.', 'AAP', true, 75),
('3ce61949-725f-59d4-8ed5-5abbab352883'::uuid, 'az', 'health', 'Hərarəti olan körpəni necə geyindirmək lazımdır?', '["Qalın yorğana bükmək", "Yüngül geyindirmək", "Spirtlə silmək", "Soyuq suya salmaq"]'::jsonb, 1, 'Spirt dəri ilə sorula bilər və təhlükəlidir. Bol maye ver.', 'AAP', true, 76),
('5b0a8d71-a082-50e7-a5aa-ffa643478308'::uuid, 'az', 'safety', 'Körpə avtomobil oturacağında neçə yaşa qədər arxaya baxaraq oturmalıdır?', '["Qucaqda saxlamaq olar", "Ən azı 2 yaşa qədər, mümkünsə daha uzun", "1 aylığa qədər", "6 aylığa qədər"]'::jsonb, 1, 'Arxaya baxan oturacaq qəzada baş və boynu ən yaxşı qoruyur.', 'AAP', true, 77),
('a691c595-079f-5d6a-846c-37dbb92dd9f4'::uuid, 'az', 'safety', 'Körpə otağında hansı əşya boğulma riski yaradır?', '["Bağlı kitab rəfi", "Pərdə və jalüzi ipləri", "Gecə lampası", "Divardakı şəkil"]'::jsonb, 1, 'İpləri körpənin əli çatmayan hündürlükdə bağla və ya ipsiz pərdə seç.', 'CPSC', true, 78),
('9a5224a0-bf3d-5cac-9750-903cce199130'::uuid, 'az', 'safety', 'Körpəni çimizdirərkən onu suda nə qədər tək qoymaq olar?', '["Böyük qardaşı ilə olar", "Bir saniyə də olmaz", "Bir dəqiqə olar", "Oyuncaqla olar"]'::jsonb, 1, 'Körpə bir neçə santimetr suda belə boğula bilər.', 'AAP', true, 79),
('0f43d707-4820-52bf-92b8-6816a2290a33'::uuid, 'az', 'safety', 'Körpənin çimmə suyu təxminən neçə dərəcə olmalıdır?', '["Təxminən 37°C", "45°C", "25°C", "50°C"]'::jsonb, 0, 'Termometr yoxdursa, suyu dirsəyinlə yoxla: ilıq olmalıdır.', 'NHS', true, 80),
('b267a62c-0fbb-5a85-96da-1e66bd0788bc'::uuid, 'az', 'safety', 'Dərmanlar və təmizləyici vasitələr harada saxlanmalıdır?', '["Kilidli, uşağın əli çatmayan yerdə", "Stolun üstündə", "Aşağı rəfdə", "Çantada"]'::jsonb, 0, 'Zəhərlənmə şübhəsi olarsa, dərhal təcili yardıma zəng et.', 'ÜST', true, 81),
('478c67b0-86e4-5383-a5f8-59e4b698b147'::uuid, 'az', 'safety', 'Körpəni maşında tək qoymaq olarmı?', '["Pəncərə açıqdırsa olar", "Qışda olar", "5 dəqiqə olar", "Heç vaxt, hətta bir neçə dəqiqəlik"]'::jsonb, 3, 'Maşın bir neçə dəqiqədə həddən artıq qıza bilər.', 'AAP', true, 82),
('487b4169-5a3e-5817-85da-c4656389ce88'::uuid, 'az', 'safety', 'Uşaq düymə batareya udarsa, nə etmək lazımdır?', '["Qusdurmaq", "Səhərə qədər gözləmək", "Dərhal təcili yardıma müraciət etmək", "Çox su içirtmək"]'::jsonb, 2, 'Batareya iki saat ərzində ciddi yanıq yarada bilər.', 'AAP', true, 83),
('995b16a3-871b-5b3a-8cd2-868578abddd3'::uuid, 'az', 'safety', 'Ağlayan körpəni silkələmək haqqında hansı fikir doğrudur?', '["Yüngül silkələmək olar", "Yuxunu yaxşılaşdırır", "Heç vaxt olmaz, beyin zədəsi yarada bilər", "Sakitləşdirir"]'::jsonb, 2, 'Əsəbləşirsənsə, körpəni təhlükəsiz yerə qoy və bir neçə dəqiqə nəfəs al.', 'CDC', true, 84),
