('8460a412-e1c3-5e9e-b335-c77733e31ed6'::uuid, 'az', 'safety', 'Şkafın və televizorun aşmasının qarşısını necə almaq olar?', '["Aşağı çəkmələri açıq saxlamaq", "Üstünə oyuncaq qoymaq", "Heç nə lazım deyil", "Onları divara bərkitmək"]'::jsonb, 3, 'Uşaq çəkmələrə çıxanda ağır mebel aşa bilər.', 'CPSC', true, 86),
('a22c5aed-bb20-5a9e-b4fa-2d24d564f58f'::uuid, 'az', 'safety', 'Pilləkən üçün ən təhlükəsiz həll hansıdır?', '["Yuxarıda və aşağıda qoruyucu qapı", "Uşağa xəbərdarlıq etmək", "Yalnız aşağıda xalça", "Heç nə"]'::jsonb, 0, 'Yuxarıdakı qapı divara vintlə bərkidilən növ olmalıdır.', 'AAP', true, 87),
('6dd193f4-04f5-58c7-bc96-df12de6c6c15'::uuid, 'az', 'safety', 'Elektrik prizlərini necə qorumaq lazımdır?', '["Lentlə yapışdırmaq", "Qoruyucu qapaqlarla", "Mebel arxasında saxlamaq kifayətdir", "Heç nə"]'::jsonb, 1, 'Uzatma kabellərini də uşağın əli çatmayan yerə qoy.', 'AAP', true, 88),
('1f2e67dc-9d3f-59a3-89ab-db8a42a0b045'::uuid, 'az', 'safety', 'Dəyişdirmə masasında körpəni nə qədər tək qoymaq olar?', '["Bir an da olmaz", "Yatırsa olar", "Bir dəqiqə olar", "Kəmər yoxdursa olar"]'::jsonb, 0, 'Lazım olan hər şeyi əvvəlcədən yanına qoy, bir əlin həmişə körpənin üstündə olsun.', 'AAP', true, 89),
('fab94a03-b78a-5ab4-affc-7952bc8c52a7'::uuid, 'az', 'safety', 'Hava şarları ilə bağlı hansı fikir doğrudur?', '["Partlamış şar oyuncaqdır", "8 yaşa qədər uşağı şarla nəzarətsiz qoymaq olmaz", "Yalnız körpələr üçün risklidir", "Tamamilə təhlükəsizdir"]'::jsonb, 1, 'Partlamış şarın parçaları nəfəs yolunu tıxaya bilər.', 'CPSC', true, 90),
('a4508ab3-f648-58a8-b4d4-6f1b95dabd54'::uuid, 'az', 'postpartum', 'Doğuşdan sonra hansı qanaxma dərhal həkimə müraciət tələb edir?', '["İlk günlər qırmızı axıntı", "Bir saatda bezin tam dolması", "Bir neçə həftə zəif axıntı", "Rəngin tədricən açılması"]'::jsonb, 1, 'Böyük qan laxtası, başgicəllənmə və ya qızdırma olarsa da, dərhal kömək al.', 'ACOG', true, 91),
('a5ed7240-5a00-56b9-9574-d7641d248fb8'::uuid, 'az', 'postpartum', 'Doğuşdan sonrakı kədər nə vaxt həkimlə danışmağı tələb edir?', '["İki həftədən uzun davam edəndə", "Yalnız ilk gün", "Yalnız bir ildən sonra", "Heç vaxt, özü keçir"]'::jsonb, 0, 'Doğuşdan sonrakı depressiya müalicə olunur. Kömək istəmək güc əlamətidir.', 'ACOG', true, 92),
('cc0b99dc-980b-5b34-a3f4-07c8c56b27c1'::uuid, 'az', 'postpartum', '"Körpə hüznü" (baby blues) adətən nə qədər davam edir?', '["6 ay", "Heç keçmir", "İlk iki həftə", "1 il"]'::jsonb, 2, 'Daha uzun çəkərsə və ya güclənərsə, depressiyanı yoxlatmaq lazımdır.', 'NHS', true, 93),
('98d86721-a3ac-5129-a414-0a8795a3bee9'::uuid, 'az', 'postpartum', 'Doğuşdan sonra həkim müayinəsi nə vaxt olmalıdır?', '["Yalnız şikayət olanda", "Bir ildən sonra", "Lazım deyil", "İlk 3 həftədə əlaqə, 12 həftəyə qədər tam müayinə"]'::jsonb, 3, 'Müayinədə əhval, yuxu, qidalanma və kontrasepsiya da danışılır.', 'ACOG', true, 94),
('d4fe7983-d364-5d18-8f56-f50a9b2211bb'::uuid, 'az', 'postpartum', 'Kegel məşqləri nə üçündür?', '["Qarın əzələlərini böyütmək", "Çəki salmaq", "Ayaqları gücləndirmək", "Çanaq dibi əzələlərini gücləndirmək"]'::jsonb, 3, 'Doğuşdan sonra sidik saxlamaqda çətinliyi azaldır.', 'NHS', true, 95),
('496b8a02-6359-56b8-be08-1d975a26cee7'::uuid, 'az', 'postpartum', 'Əmizdirən ana gündə nə qədər kofein qəbul edə bilər?', '["Limitsiz", "300 mq-a qədər", "Heç olmaz", "1000 mq"]'::jsonb, 1, 'Bu, təxminən 2-3 fincan qəhvədir. Körpə narahat olarsa, azalt.', 'CDC', true, 96),
('5a91723a-ba13-54c0-ba31-8aa2247a9b4f'::uuid, 'az', 'postpartum', 'Əmizdirmə nə vaxt hamiləlikdən qoruya bilər?', '["Həmişə qoruyur", "Heç vaxt qorumur", "Yalnız gecə əmizdirəndə", "İlk 6 ay, yalnız ana südü və aybaşı olmayanda"]'::jsonb, 3, 'Bu şərtlərdən biri pozularsa, başqa üsul lazımdır. Həkimlə danış.', 'ÜST', true, 97),
('5f0b1299-4a90-5197-9765-af58a117629c'::uuid, 'az', 'postpartum', 'Doğuşdan sonra idmana necə qayıtmaq lazımdır?', '["Bir il gözləmək", "Dərhal ağır məşqlə", "Həkim icazəsi ilə tədricən, gəzintidən başlayaraq", "Heç vaxt"]'::jsonb, 2, 'Qarın əzələlərinin aralanması varsa, xüsusi məşqlər lazım ola bilər.', 'ACOG', true, 98),
('bc136785-92b9-5d4b-90d2-80ad1e518bcd'::uuid, 'az', 'postpartum', 'Mastitin əlaməti hansıdır?', '["Süd çox gəlməsi", "Döşdə qızartı, ağrı və qızdırma", "İştahanın artması", "Döşün yumşalması"]'::jsonb, 1, 'Əmizdirməni davam etdir və həkimə müraciət et.', 'ÜST', true, 99),
('da8b3f31-89c6-5bb2-b386-f098fc8fb0a5'::uuid, 'az', 'postpartum', 'Qeysəriyyədən sonra ağır əşya qaldırmamaq nə qədər tövsiyə olunur?', '["Təxminən 6 həftə", "1 il", "Heç vaxt", "Ertəsi gündən olar"]'::jsonb, 0, 'Körpəni qaldırmaq olar, amma ondan ağır əşyaları başqası qaldırsın.', 'NHS', true, 100)
